#include "Processor.h"
#include <iostream>
#include <stdexcept>
void check(bool b,const char* why){if(!b)throw std::runtime_error(why);}
int main(int argc,char**){try{std::unique_ptr<juce::ScopedJuceInitialiser_GUI> gui;if(argc>1)gui=std::make_unique<juce::ScopedJuceInitialiser_GUI>();VocaProcessor p;p.prepareToPlay(48000,256);check(p.getLatencySamples()==2048,"Host latency registration");check(p.getParameters().size()==voca::NumKnobs+voca::NumModules+11,"Host parameter count");auto* gain=p.state.getParameter("input");gain->setValueNotifyingHost(gain->convertTo0to1(5));auto* delay=p.state.getParameter("delayTime");delay->setValueNotifyingHost(delay->convertTo0to1(4));juce::MemoryBlock blob;p.getStateInformation(blob);VocaProcessor restored;restored.setStateInformation(blob.getData(),static_cast<int>(blob.getSize()));check(std::abs(restored.state.getRawParameterValue("input")->load()-5)<1e-4,"Gain session recall");check(restored.state.getRawParameterValue("delayTime")->load()==4,"Choice session recall");p.applyPreset(2);check(p.state.getRawParameterValue("lowEnd")->load()==45,"Hip hop preset character");p.resetParameters();check(p.state.getRawParameterValue("lowEnd")->load()==0,"Reset defaults");juce::MidiBuffer midi;juce::AudioBuffer<float> b(2,256);for(int block=0;block<120;++block){for(int i=0;i<256;++i){const float envelope=.05f+.95f*std::pow(std::sin(float(block)*float(voca::pi)/120),2.f);const float v=.2f*envelope*std::sin((block*256+i)*2*voca::pi*220/48000);b.setSample(0,i,v);b.setSample(1,i,v);}p.processBlock(b,midi);}check(p.outputPeak.load()>0,"Processor must emit audio");if(argc>1){std::unique_ptr<juce::AudioProcessorEditor> editor(p.createEditor());check(editor->getWidth()==1152&&editor->getHeight()==768,"Default editor dimensions");bool adjusted=false;for(int i=0;i<editor->getNumChildComponents();++i)if(auto* s=dynamic_cast<juce::Slider*>(editor->getChildComponent(i)))if(s->getName()=="Input"){s->setValue(3,juce::sendNotificationSync);adjusted=true;}check(adjusted&&std::abs(p.state.getRawParameterValue("input")->load()-3)<1e-4,"Editor control must update audio parameter");auto image=editor->createComponentSnapshot(editor->getLocalBounds());juce::File file=juce::File::getSpecialLocation(juce::File::tempDirectory).getChildFile("VocaMAX-editor.png");juce::FileOutputStream stream(file);stream.setPosition(0);stream.truncate();check(juce::PNGImageFormat().writeImageToStream(image,stream),"Editor render");editor->setSize(1536,1024);auto full=editor->createComponentSnapshot(editor->getLocalBounds());check(full.getWidth()==1536,"Resizable editor");std::cout<<"UI rendered to "<<file.getFullPathName()<<"\n";}
 std::cout<<"VocaMAX host parameters, latency, audio, presets and session recall passed\n";return 0;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
